import unittest
from datetime import datetime, timezone, timedelta
from alerts.service import should_send

class Alerts(unittest.TestCase):
    def test_midnight_boundaries(self):
        for hour,minute,expected in [(21,59,True),(22,0,False),(23,59,False),(0,0,False),(5,59,False),(6,0,True)]:
            self.assertEqual(should_send(datetime(2026,6,1,hour,minute,tzinfo=timezone.utc),0,1320,360),expected)
        self.assertTrue(should_send(datetime(2026,6,1,tzinfo=timezone.utc),0,0,0))
    def test_actual_instant_and_half_hour_offset(self):
        instant=datetime(2026,6,1,22,tzinfo=timezone(timedelta(hours=8)))
        self.assertTrue(should_send(instant,0,1320,360))
        self.assertFalse(should_send(instant,480,1320,360))
        self.assertFalse(should_send(datetime(2026,6,1,3,30,tzinfo=timezone.utc),330,540,600))
        with self.assertRaises(ValueError): should_send(datetime(2026,6,1),0,0,60)

if __name__ == '__main__':
    unittest.main()

